-- 6. consultas para verificar que la data se haya subido correctamente
-- RESERVA 486, TRANSACCION_USO 396, TICKET_MANTENIMIENTO 10, LOG_EVENTO_IOT 377
SELECT 'RESERVA' AS TABLA, COUNT(*) AS FILAS FROM RESERVA WHERE FECHA_SOLICITUD < TIMESTAMP '2026-09-18 00:00:00'
UNION ALL SELECT 'TRANSACCION_USO', COUNT(*) FROM TRANSACCION_USO WHERE FECHA_INICIO < TIMESTAMP '2026-09-18 00:00:00'
UNION ALL SELECT 'TICKET_MANTENIMIENTO', COUNT(*) FROM TICKET_MANTENIMIENTO WHERE FECHA_REPORTE < TIMESTAMP '2026-09-18 00:00:00'
UNION ALL SELECT 'LOG_EVENTO_IOT', COUNT(*) FROM LOG_EVENTO_IOT WHERE FECHA_EVENTO < TIMESTAMP '2026-09-18 00:00:00';

-- Reservas concretadas sin uso. Debe mostrar 0
SELECT COUNT(*) AS CONCRETADAS_SIN_USO
  FROM RESERVA r
 WHERE r.FECHA_SOLICITUD < TIMESTAMP '2026-09-18 00:00:00'
   AND r.ESTADO_RESERVA = 'CONCRETADA'
   AND NOT EXISTS (SELECT 1 FROM TRANSACCION_USO t WHERE t.ID_RESERVA = r.ID_RESERVA);

-- Horas punta. Debe mostrar la de las 8 diurno y 19 vespertino
SELECT HORA_INICIO, COUNT(*) AS USOS
  FROM V_HECHO_USO
 WHERE FECHA < DATE '2026-09-18'
 GROUP BY HORA_INICIO
 ORDER BY USOS DESC, HORA_INICIO;

